<template>
  <div class="flex flex-col items-center gap-4 text-center">
    <!-- Picture (click to enlarge) or empty placeholder -->
    <ImagePreviewDialog
      v-if="hasContent && profilePictureUrl"
      :src="profilePictureOriginalUrl ?? profilePictureUrl"
      alt="Profile picture"
      title="Profile picture"
      description="Enlarged profile picture preview."
    >
      <template #trigger>
        <img
          :src="profilePictureUrl"
          alt="Profile picture"
          class="size-32 cursor-pointer rounded-full object-cover ring-4 ring-muted"
          data-testid="profile-bio-display-picture"
        />
      </template>
    </ImagePreviewDialog>
    <div v-else class="flex size-32 items-center justify-center rounded-full bg-muted ring-4 ring-muted">
      <UserRoundIcon class="size-12 text-muted-foreground" />
    </div>

    <!-- Name + role -->
    <div v-if="fullName || roleLabel" class="flex flex-col gap-1">
      <h3 v-if="fullName" class="text-xl font-semibold" data-testid="profile-bio-display-name">{{ fullName }}</h3>
      <span v-if="roleLabel" class="text-sm text-muted-foreground" data-testid="profile-bio-display-role">{{
        roleLabel
      }}</span>
    </div>

    <!-- Meta row: hidden entirely in the empty state -->
    <div
      v-if="hasContent && (location || joinedLabel)"
      class="flex flex-wrap items-center justify-center gap-x-4 gap-y-2 text-sm text-muted-foreground"
    >
      <span v-if="location" class="flex items-center gap-1.5" data-testid="profile-bio-display-location">
        <MapPinIcon class="size-4 shrink-0" />
        {{ location }}
      </span>
      <span v-if="joinedLabel" class="flex items-center gap-1.5" data-testid="profile-bio-display-joined">
        <CalendarDaysIcon class="size-4 shrink-0" />
        {{ joinedLabel }}
      </span>
    </div>

    <!-- Bio or empty message -->
    <p
      v-if="hasContent && bio"
      class="max-w-prose text-sm leading-relaxed text-muted-foreground"
      data-testid="profile-bio-display-bio"
    >
      {{ bio }}
    </p>
    <p v-else-if="!hasContent" class="text-sm text-muted-foreground" data-testid="profile-bio-display-empty">
      {{ emptyMessage }}
    </p>
  </div>
</template>

<script setup lang="ts">
import { CalendarDaysIcon, MapPinIcon, UserRoundIcon } from 'lucide-vue-next';
import type { UserRole } from '~/client';
import { getUserRole } from '~/constants/users/userRoles';

interface Props {
  bio: string | null;
  profilePictureUrl: string | null;
  profilePictureOriginalUrl: string | null;
  emptyMessage?: string;
  fullName?: string | null;
  role?: UserRole | null;
  city?: string | null;
  state?: string | null;
  joinedAt?: string | null;
}

const props = withDefaults(defineProps<Props>(), {
  emptyMessage: 'No profile information provided',
  fullName: null,
  role: null,
  city: null,
  state: null,
  joinedAt: null,
});

const hasContent = computed(() => Boolean(props.bio || props.profilePictureUrl));
const roleLabel = computed(() => (props.role ? getUserRole(props.role).name : null));
const location = computed(() => [props.city, props.state].filter(Boolean).join(', ') || null);
const joinedLabel = computed(() =>
  props.joinedAt ? `Joined ${formatDateToFormat(new Date(props.joinedAt), 'MMMM yyyy')}` : null
);
</script>
